INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65576265', 65576265, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'BANDAR UDARA MOZES KILANGIN TIMIKA', 'PENYUSUNAN AMANDEMEN DOKUMEN AM DAN SMS', 'Barang', 'Pengadaan Langsung', 'Papua Tengah, Mimika (Kab.)', 200001000, 'February 2026', 'APBN - BADAN LAYANAN UMUM (F)', 1, 1, '1 Paket', '1. Belanja Barang;', 'Berikut Spesifikasi Teknis Pekerjaan Penyusunan Dokumen AM dan SMS dalam 1 paragraf, dengan redaksi formal dan siap dimasukkan ke KAK: Pekerjaan penyusunan dokumen Aerodrome Manual (AM) dan Safety Management System (SMS) merupakan kegiatan penyusunan dan/atau pembaruan dokumen operasional bandar udara yang memuat standar prosedur, struktur organisasi, tanggung jawab, serta sistem pengelolaan keselamatan sesuai regulasi penerbangan yang berlaku. Ruang lingkup pekerjaan meliputi pengumpulan dan verifikasi data operasional bandara, identifikasi kesesuaian terhadap ketentuan teknis dan keselamatan, penyusunan manual AM yang mencakup fasilitas, prosedur operasi, pemeliharaan, dan koordinasi layanan kebandarudaraan, serta penyusunan dokumen SMS yang meliputi kebijakan keselamatan, manajemen risiko, pelaporan kejadian, jaminan keselamatan, dan promosi keselamatan. Pelaksanaan pekerjaan dilakukan secara sistematis dan terdokumentasi dengan melibatkan unit terkait, sehingga menghasilkan dokumen AM dan SMS yang komprehensif, mutakhir, dan dapat digunakan sebagai pedoman resmi dalam mendukung operasional bandar udara yang aman, tertib, dan sesuai peraturan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2246846);
