INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65612773', 65612773, 'analyze_legacy', 'Kota Banjar', 'kabkota', 'UPTD RUMAH SAKIT UMUM', 'Belanja Jasa Pembersihan, Pengendalian Hama, dan Fumigasi', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Banjar (Kota)', 103656000, 'February 2026', 'BLUD', 1, 1, '1 Tahun', 'Meliputi kegiatan pembersihan dan sanitasi area dalam dan luar gedung, termasuk ruangan pelayanan, perkantoran, koridor, toilet, dan area publik lainnya; pengendalian hama seperti tikus, kecoa, semut, nyamuk, dan serangga lainnya melalui metode monitoring, pemasangan perangkap, penyemprotan, atau tindakan teknis lain yang aman; serta pelaksanaan fumigasi pada area tertentu sesuai kebutuhan dengan menggunakan bahan kimia yang terdaftar dan aman, dikerjakan oleh tenaga profesional bersertifikat dengan penggunaan APD lengkap, peralatan yang memenuhi standar, serta dilaksanakan sesuai ketentuan K3 dan peraturan perundang-undangan yang berlaku, termasuk penyampaian laporan hasil kegiatan secara berkala.', 'Penyediaan tenaga kerja terlatih dan bersertifikat dengan APD lengkap, penggunaan peralatan dan bahan pembersih serta pestisida/fumigan yang terdaftar dan aman sesuai standar kesehatan, pelaksanaan pembersihan rutin area dalam dan luar gedung, pengendalian hama melalui metode terpadu (monitoring, perangkap, penyemprotan), serta fumigasi sesuai kebutuhan dengan prosedur keselamatan yang ketat, dilaksanakan berdasarkan jadwal yang ditetapkan dan disertai laporan hasil kegiatan secara berkala sesuai ketentuan K3 dan peraturan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2247605);
