INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65576261', 65576261, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'BANDAR UDARA MOZES KILANGIN TIMIKA', 'EVALUASI SBU', 'Barang', 'Pengadaan Langsung', 'Papua Tengah, Mimika (Kab.)', 200000000, 'February 2026', 'APBN - BADAN LAYANAN UMUM (F)', 1, 1, '1 Paket', '1. Belanja Barang;', 'Pekerjaan evaluasi Standar Pelayanan Bandar Udara (SBU) merupakan kegiatan penilaian dan pengukuran tingkat pemenuhan standar pelayanan terhadap pengguna jasa bandara guna memastikan kualitas layanan sesuai ketentuan yang berlaku. Ruang lingkup pekerjaan meliputi pengumpulan dan verifikasi data kinerja pelayanan, survei kepuasan pengguna jasa, observasi fasilitas dan proses pelayanan di terminal maupun sisi darat, analisis kesenjangan (gap analysis) antara kondisi eksisting dengan standar yang ditetapkan, serta penyusunan rekomendasi perbaikan dan peningkatan layanan. Pelaksanaan evaluasi dilakukan secara sistematis dan terdokumentasi, dengan hasil akhir berupa laporan evaluasi SBU yang memuat temuan, tingkat capaian indikator pelayanan, serta rencana tindak lanjut sebagai dasar peningkatan mutu pelayanan bandar udara secara berkelanjutan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2247660);
