INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65576260', 65576260, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'BANDAR UDARA MOZES KILANGIN TIMIKA', 'IMPLEMENTASI SMS', 'Barang', 'Pengadaan Langsung', 'Papua Tengah, Mimika (Kab.)', 100000000, 'February 2026', 'APBN - BADAN LAYANAN UMUM (F)', 1, 1, '1 Paket', '1. Belanja Barang;', 'Pekerjaan implementasi Safety Management System (SMS) merupakan kegiatan penerapan sistem manajemen keselamatan secara terstruktur dan terdokumentasi guna meningkatkan budaya keselamatan serta pengendalian risiko operasional di lingkungan bandar udara. Ruang lingkup pekerjaan meliputi identifikasi bahaya (hazard identification), penilaian dan mitigasi risiko (risk assessment and mitigation), penyusunan atau pembaruan dokumen manual SMS, pengembangan prosedur pelaporan kejadian (occurrence reporting system), pelaksanaan sosialisasi dan pelatihan kepada personel, serta evaluasi efektivitas penerapan SMS melalui monitoring dan internal review. Pelaksanaan kegiatan harus mengacu pada regulasi keselamatan penerbangan yang berlaku dan standar sistem manajemen keselamatan, dengan output berupa dokumen SMS yang terdokumentasi, mekanisme pelaporan yang berjalan efektif, serta peningkatan pemahaman dan komitmen personel terhadap aspek keselamatan dalam mendukung operasional bandar udara yang aman dan berkelanjutan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2248145);
